                ctx.strokeStyle = '#64748B';
                ctx.lineWidth = 1;
                ctx.strokeRect(box.x - 1, box.y - 1, w + 2, h + 2);
            }

            const finalDataUrl = canvas.toDataURL('image/png');
            setLocalBiometricSheetUrl(finalDataUrl);
