    // --- SHOTS (Storyboard) ---
    // Shots live in AppContext so SceneCanvas / Veo / Production stay in sync.
    const [newShotName, setNewShotName] = useState('');
    const [activeShotNameDraft, setActiveShotNameDraft] = useState('');

