    };

    const setSlotFromUrl = async (index: number, url: string, name?: string, castId?: string, localPath?: string, sourceUrl?: string) => {
        updateRefSlot(index, {
            url,
            localPath,
            sourceUrl,
            name: name || `Ref ${index}`,
