    const handleRefSlotFile = async (index: number, file: File) => {
        try {
            const tempUrl = await fileToDataUrl(file);
            const mat = await LibraryAssetMaterializer.materializeReferenceAsset({
                sourceUrl: tempUrl,
                saveDirectoryPath: state.saveDirectoryPath,
