                                                    />
                                                    {brandingLogo && (
                                                        <button
                                                            onClick={(e) => { e.preventDefault(); setBrandingLogo(null); }}
                                                            className="absolute -top-2 -right-2 bg-red-500 text-white w-6 h-6 rounded-full flex items-center justify-center hover:bg-red-400 transition-all"
